{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Gatherings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfc;--card:#fff;--muted:#6b6f76;--accent:#6b4eff;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#222;background:linear-gradient(180deg,#f7f7fb 0%,var(--bg) 100%);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:radial-gradient(1200px 200px at 10% 0%,rgba(107,78,255,0.06),transparent 20%),transparent;backdrop-filter:blur(6px)}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;border-radius:8px;background:conic-gradient(from 200deg,#ffd7e6,#fff3d1,#dfeaff);display:grid;place-items:center;font-weight:700;color:#2b2b2b}
    nav a{margin-left:18px;text-decoration:none;color:var(--muted);font-weight:600}
    main{max-width:1100px;margin:28px auto;padding:20px}

    /* pattern background */
    .hero{position:relative;padding:36px;border-radius:12px;background-image:url('assets/img/pattern.svg');background-size:240px;background-repeat:no-repeat;background-position:95% 10%;background-color:var(--card);box-shadow:0 6px 30px rgba(18,18,18,0.04);display:grid;grid-template-columns:1fr 340px;gap:20px}
    .hero h1{margin:0 0 8px;font-size:28px}
    .hero p{margin:0;color:var(--muted)}
    .next-event{background:linear-gradient(180deg,rgba(107,78,255,0.06),transparent);padding:18px;border-radius:10px;border:1px solid rgba(107,78,255,0.08)}
    .next-event time{display:block;font-weight:700;font-size:14px}
    .next-event .meta{color:var(--muted);font-size:13px;margin-top:8px}

    .grid{display:grid;grid-template-columns:1fr 320px;gap:20px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(15,15,15,0.03)}
    .calendar{display:flex;flex-direction:column;gap:10px}
    .cal-item{display:flex;align-items:center;gap:12px;padding:10px;border-radius:8px;background:linear-gradient(180deg,#fff,rgba(255,255,255,0.96));border:1px solid rgba(18,18,18,0.02)}
    .cal-item .date{width:64px;padding:8px;border-radius:8px;background:rgba(107,78,255,0.06);text-align:center;font-weight:700}
    .muted{color:var(--muted);font-size:13px}

    /* reveal */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}}

    footer{margin-top:28px;padding:18px;text-align:center;color:var(--muted);font-size:13px}

    .cta{display:inline-block;padding:10px 14px;border-radius:9px;background:var(--accent);color:#fff;text-decoration:none;font-weight:700}
    small.disclaimer{display:block;color:#8b0d0d;background:linear-gradient(180deg,rgba(255,235,235,0.8),transparent);padding:10px;border-radius:8px;margin-top:12px}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Main navigation">
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">One-on-One</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">About</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal" aria-labelledby="hero-title">
      <div>
        <h1 id="hero-title">Upcoming communal sound sessions</h1>
        <p>Join short-form gatherings tuned to settle thought, soften shoulders, and reset habitual breath. Sessions are small, acoustically mindful, and offered in a gentle cohort model.</p>
        <p style="margin-top:12px"><a class="cta" href="{{PRIMARY_CTA_URL}}">Reserve a seat</a></p>
      </div>
      <aside>
        <div class="next-event" id="next-event" aria-live="polite">
          <div style="font-size:12px;color:var(--muted);">Next session</div>
          <time id="next-date">—</time>
          <div class="meta" id="next-meta">Loading…</div>
          <div style="margin-top:10px"><a href="book.html" class="cta" style="background:#2bba9b">Save my spot</a></div>
        </div>
      </aside>
    </section>

    <div class="grid">
      <section class="card reveal" aria-labelledby="list-title">
        <h2 id="list-title">Calendar & upcoming gatherings</h2>
        <p class="muted">Cohort-style gatherings open to a small number of guests. Titles are suggestive of focus, not prescriptive of outcome.</p>
        <div class="calendar" id="calendar-list" role="list"></div>
      </section>

      <aside class="card reveal" aria-labelledby="what-title">
        <h3 id="what-title">What to expect</h3>
        <p class="muted">Rooms are calm and dimly lit. Sessions begin with simple orientation, followed by guided resonant sound. Expect periods of silence, and a careful close. Come as you are — you can sit, lie, or use the provided bolsters.</p>

        <h4 style="margin-top:12px">Accessibility</h4>
        <p class="muted">If you have questions about accessibility or need a quieter seat, contact us at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>

        <small class="disclaimer">Contraindications: if you have uncontrolled epilepsy, recent major surgery, or are pregnant and have concerns, consult your medical provider before attending. For anyone with a history of severe PTSD or dissociation, consider checking in with a clinician first.</small>
      </aside>
    </div>

    <section class="card reveal" style="margin-top:18px" aria-labelledby="how-title">
      <h3 id="how-title">How we choose the next dates</h3>
      <p class="muted">We seed dates based on community demand and local availability. Spots are intentionally limited so cohorts stay intimate. If a date fills, add your name to the waitlist and we’ll notify you when a new cohort opens.</p>
      <p style="margin-top:12px"><a href="book.html" class="cta">Join the waitlist</a></p>
    </section>

    <footer>
      <div class="muted">Sessions in {{CITY}}, {{STATE}} • Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </footer>
  </main>

  <script>
    // Scroll reveal with reduced motion respect
    document.addEventListener('DOMContentLoaded',function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = document.querySelectorAll('.reveal');
      if(prefersReduced){
        reveals.forEach(el=>el.classList.add('visible'));
      } else if('IntersectionObserver' in window){
        const io = new IntersectionObserver((entries,obs)=>{
          entries.forEach(e=>{
            if(e.isIntersecting){
              e.target.classList.add('visible');
              obs.unobserve(e.target);
            }
          })
        },{threshold:0.12});
        reveals.forEach(r=>io.observe(r));
      } else {
        reveals.forEach(el=>el.classList.add('visible'));
      }

      // Events dataset and next-event module
      const events = [
        {iso:'2026-03-05T18:30:00',title:'Evening Ease — soft pans & bowls',location:'Studio A'},
        {iso:'2026-03-19T10:30:00',title:'Midday Hush — daylight cohort',location:'Studio B'},
        {iso:'2026-04-02T19:00:00',title:'Quiet Harbor — slow gong session',location:'Studio A'},
        {iso:'2026-04-16T09:30:00',title:'Breath & Bowls — gentle morning',location:'Community Hall'},
        {iso:'2026-05-01T18:30:00',title:'Liminal Tones — ritual-free sound',location:'Studio A'},
        {iso:'2026-05-20T19:00:00',title:'Stillness Practice — closed cohort',location:'Studio C'}
      ];

      function parseISO(s){return new Date(s)}
      const now = new Date();
      const future = events.filter(e=>parseISO(e.iso)>now).sort((a,b)=>parseISO(a.iso)-parseISO(b.iso));
      const next = future[0];
      const nextDateEl = document.getElementById('next-date');
      const nextMetaEl = document.getElementById('next-meta');
      if(next){
        const d = parseISO(next.iso);
        nextDateEl.textContent = d.toLocaleString(undefined,{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'numeric'});
        nextMetaEl.textContent = next.title + ' • ' + next.location;
      } else {
        nextDateEl.textContent = 'No dates scheduled';
        nextMetaEl.textContent = 'Check back soon or contact us to request a cohort.';
      }

      // Build calendar list
      const calList = document.getElementById('calendar-list');
      future.slice(0,8).forEach(ev=>{
        const d = parseISO(ev.iso);
        const item = document.createElement('div');
        item.className = 'cal-item';
        item.setAttribute('role','listitem');
        item.innerHTML = '<div class="date">'+d.toLocaleDateString(undefined,{month:'short',day:'numeric'})+'</div>'+
                         '<div style="flex:1"><div style="font-weight:700">'+ev.title+'</div><div class="muted">'+d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})+' • '+ev.location+'</div></div>'+
                         '<div><a href="book.html" class="cta" style="background:#6b4eff;padding:8px 10px;font-size:13px">Book</a></div>';
        calList.appendChild(item);
      });
    });
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Private Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8fafb;--card:#fff;--muted:#60646b;--accent:#ff6b6b}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;color:#222;background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 22px;background:#fff;border-bottom:1px solid rgba(7,7,7,0.04)}
    .logo{width:44px;height:44px;border-radius:9px;background:linear-gradient(135deg,#ffd8e6,#dfe6ff);display:grid;place-items:center;font-weight:800}
    nav a{margin-left:16px;text-decoration:none;color:var(--muted);font-weight:600}

    main{max-width:980px;margin:24px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 380px;gap:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(10,10,10,0.03)}

    h1{margin:0 0 8px}
    p.lead{color:var(--muted);margin-top:0}

    /* Planner */
    .planner label{display:block;font-size:13px;margin-top:12px}
    .planner input,.planner select,.planner textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(11,11,11,0.06);margin-top:8px}
    .row{display:flex;gap:10px}
    .small{flex:1}
    .btn{display:inline-block;padding:10px 14px;border-radius:10px;border:none;background:var(--accent);color:#fff;font-weight:800;text-decoration:none;cursor:pointer}
    .secondary{background:#fff;border:1px solid rgba(11,11,11,0.06);color:var(--muted)}
    pre.output{white-space:pre-wrap;background:#f6f8fb;padding:12px;border-radius:8px;border:1px dashed rgba(11,11,11,0.04);margin-top:12px}

    .reveal{opacity:0;transform:translateY(14px);transition:opacity .5s ease,transform .5s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}}

    .disclaimer{font-size:13px;color:#7a1212;background:rgba(255,235,235,0.8);padding:8px;border-radius:8px;margin-top:12px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">PS</div>
      <div><div style="font-weight:800">{{BUSINESS_NAME}}</div><div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div></div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Personal Sessions</a>
      <a href="pricing.html">Rates</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="card reveal" aria-labelledby="ps-title">
      <h1 id="ps-title">Private sound sessions</h1>
      <p class="lead">Tailored, quieter, and paced for your attention. Private work is ideal when you want a focus, a ceremony, or a paced series with personal continuity.</p>
      <p style="margin-top:12px"><a class="btn" href="{{PRIMARY_CTA_URL}}">Request a private</a></p>
    </section>

    <div class="grid">
      <section class="card reveal" aria-labelledby="planner-title">
        <h2 id="planner-title">Session Planner</h2>
        <p class="muted">Build a short brief for your session. You can copy the plain-text summary and paste it into the booking form or an email to us.</p>
        <form id="planner" class="planner" onsubmit="return false;">
          <label>Session format</label>
          <select id="format">
            <option value="solo">Solo — one person</option>
            <option value="duo">Duo — two people</option>
            <option value="small-group">Small group (3–6)</option>
            <option value="couple">Couple / partnered session</option>
          </select>

          <div class="row">
            <div class="small">
              <label>Length</label>
              <select id="length"><option value="30">30 minutes</option><option value="45">45 minutes</option><option value="60" selected>60 minutes</option><option value="90">90 minutes</option></select>
            </div>
            <div class="small">
              <label>Frequency</label>
              <select id="frequency"><option value="one">One-off</option><option value="weekly">Weekly</option><option value="biweekly">Bi-weekly</option><option value="monthly">Monthly</option></select>
            </div>
          </div>

          <label>Primary focus / intention</label>
          <textarea id="intent" rows="3" placeholder="e.g., regain calm after travel; prepare for a presentation; help a loved one with sleep"></textarea>

          <label>Preferred instruments (optional)</label>
          <select id="palette">
            <option value="bowls">Crystal & metal bowls</option>
            <option value="gong">Gong & low tones</option>
            <option value="chimes">Light chimes & overtone work</option>
            <option value="voice">Voice-led tuning & breath</option>
            <option value="adaptive">Allow practitioner to choose</option>
          </select>

          <label>Notes / Accessibility needs</label>
          <input id="notes" placeholder="Sensitivity to loud bangs, prefer dim lights, need a chair" />

          <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
            <button id="build" class="btn" type="button">Create summary</button>
            <button id="copy" class="btn secondary" type="button">Copy summary</button>
            <button id="prefill" class="btn secondary" type="button">Prefill booking</button>
          </div>

          <pre id="output" class="output" aria-live="polite">No summary yet — click \"Create summary\".</pre>
        </form>

        <div class="disclaimer">Contraindications: People with photosensitive epilepsy or certain cardiac implants should consult a clinician before attending. If you are pregnant, recently had surgery, or have active psychiatric crisis, please speak with your provider first.</div>
      </section>

      <aside class="card reveal" aria-labelledby="why-title">
        <h3 id="why-title">How a private session works</h3>
        <ol class="muted" style="padding-left:18px;margin:0">
          <li>Short intake — clarify intent and comfort preferences.</li>
          <li>Gentle orientation to lying or seated position and optional mindfulness anchor.</li>
          <li>Sound work — paced to your nervous system, with quiet pauses and gradual close.</li>
        </ol>

        <h4 style="margin-top:12px">Contact</h4>
        <p class="muted">Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a> to discuss specific needs. Private sessions can be in-studio or arranged in a home visit within {{CITY}} area.</p>
      </aside>
    </div>

    <footer style="text-align:center;margin-top:18px;color:var(--muted)">Prices start from a cohort-aware baseline. Use the planner to create a booking brief and paste it into the request form.</footer>
  </main>

  <script>
    // Reveal with reduced motion
    document.addEventListener('DOMContentLoaded',function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('.reveal');
      if(prefersReduced) els.forEach(e=>e.classList.add('visible'));
      else if('IntersectionObserver' in window){
        const io = new IntersectionObserver((entries,obs)=>{
          entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); obs.unobserve(en.target);} });
        },{threshold:0.12});
        els.forEach(e=>io.observe(e));
      } else els.forEach(e=>e.classList.add('visible'));

      // Planner logic
      const build = document.getElementById('build');
      const copy = document.getElementById('copy');
      const prefill = document.getElementById('prefill');
      const output = document.getElementById('output');

      function recommendInstruments(palette){
        const map = {bowls:'singing bowls and soft mallets',gong:'gongs and deep drone',chimes:'light chimes and subtle bells',voice:'voice-tuning and breath guidance',adaptive:'a custom mix tuned to you'};
        return map[palette]||'a gentle mix';
      }

      function suggestPackage(format,length,frequency){
        const base = parseInt(length,10);
        let label = base<=30? 'Brief Focus':'Standard Session';
        if(format==='small-group') label = 'Shared Private — small group';
        if(frequency==='weekly') label += ' (series)';
        return label;
      }

      function buildSummary(){
        const format = document.getElementById('format').value;
        const length = document.getElementById('length').value;
        const frequency = document.getElementById('frequency').value;
        const intent = document.getElementById('intent').value.trim();
        const palette = document.getElementById('palette').value;
        const notes = document.getElementById('notes').value.trim();

        const instruments = recommendInstruments(palette);
        const packageName = suggestPackage(format,length,frequency);

        const lines = [];
        lines.push('Private session brief');
        lines.push('---------------------');
        lines.push('Requested format: '+format.replaceAll('-',' '));
        lines.push('Length: '+length+' minutes');
        lines.push('Frequency: '+frequency);
        lines.push('Focus / intention: '+(intent||'Not specified'));
        lines.push('Suggested sound palette: '+instruments);
        lines.push('Suggested package: '+packageName);
        if(notes) lines.push('Accessibility / notes: '+notes);
        lines.push('Contact: '+{{EMAIL ? '"'+String('{{EMAIL}}')+'"' : '"'+'{{EMAIL}}'+'"'}});
        lines.push('Location: '+{{CITY ? '"'+String('{{CITY}}')+'"' : '"'+'{{CITY}}'+'"'}}+', '+{{STATE ? '"'+String('{{STATE}}')+'"' : '"'+'{{STATE}}'+'"'}});

        return lines.join('\n');
      }

      build.addEventListener('click',function(){
        const summary = buildSummary();
        output.textContent = summary;
      });

      copy.addEventListener('click',async function(){
        const text = output.textContent;
        if(!text || text.includes('No summary')) return alert('Create a summary first');
        try{
          await navigator.clipboard.writeText(text);
          copy.textContent = 'Copied!';
          setTimeout(()=>copy.textContent='Copy summary',1300);
        }catch(e){
          // fallback
          const ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); try{ document.execCommand('copy'); alert('Copied'); }catch(err){ alert('Copy failed') } ta.remove();
        }
      });

      prefill.addEventListener('click',function(){
        const summary = encodeURIComponent(buildSummary());
        const url = '{{PRIMARY_CTA_URL}}?brief='+summary;
        window.location.href = url;
      });
    });
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates & Cohorts — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff9f4;--card:#fff;--muted:#5b5f65;--accent:#5b8cff}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#222;background:var(--bg)}
    header{display:flex;justify-content:space-between;padding:14px 20px;background:linear-gradient(180deg,#fff,#fff0)}
    nav a{margin-left:14px;text-decoration:none;color:var(--muted);font-weight:600}
    main{max-width:1100px;margin:18px auto;padding:18px}

    .hero{display:flex;align-items:center;justify-content:space-between;padding:22px;border-radius:12px;background:linear-gradient(90deg,rgba(91,140,255,0.06),transparent);border:1px solid rgba(91,140,255,0.06)}
    .tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .tier{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(10,10,10,0.03);text-align:center}
    .price{font-size:22px;font-weight:800;margin-top:6px}
    .muted{color:var(--muted)}

    .planner{margin-top:18px;padding:14px;background:linear-gradient(180deg,#fff,#fffaf2);border-radius:12px;border:1px solid rgba(10,10,10,0.03)}
    .planner input,.planner select{padding:8px;border-radius:8px;border:1px solid rgba(10,10,10,0.06);width:100%}
    .row{display:flex;gap:10px}

    .btn{background:var(--accent);color:#fff;border:none;padding:10px 14px;border-radius:10px;font-weight:800;cursor:pointer}

    .reveal{opacity:0;transform:translateY(12px);transition:opacity .5s ease,transform .5s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Personal Sessions</a>
      <a href="pricing.html">Rates</a>
      <a href="faq.html">FAQ</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal" aria-labelledby="rates-title">
      <div>
        <h1 id="rates-title">Cohort-based pricing & private options</h1>
        <p class="muted">We emphasize small cohorts to keep things intimate. Below are common formats; each booking can be tailored. Use the planner to estimate per-person cost for your group.</p>
      </div>
      <div><a class="btn" href="book.html">Start a cohort request</a></div>
    </section>

    <section class="tiers reveal" aria-label="Pricing tiers">
      <div class="tier">
        <div style="font-weight:700">Cohort Session</div>
        <div class="price">$28 / person</div>
        <div class="muted">(60 min, min 6 people)</div>
        <p class="muted" style="font-size:13px">Best for regular short gatherings. Price per-person decreases for larger groups.</p>
      </div>
      <div class="tier">
        <div style="font-weight:700">Private One</div>
        <div class="price">from $120</div>
        <div class="muted">(one-on-one, 60 min)</div>
        <p class="muted" style="font-size:13px">Personalized pacing and additional intake time included.</p>
      </div>
      <div class="tier">
        <div style="font-weight:700">Series & Workplace</div>
        <div class="price">Custom</div>
        <div class="muted">(packages for teams or recurring cohorts)</div>
        <p class="muted" style="font-size:13px">We design a cohort cadence to suit your group size and goals.</p>
      </div>
    </section>

    <section class="card planner reveal" aria-labelledby="planner-title">
      <h2 id="planner-title">Cohort Cost Planner</h2>
      <p class="muted">Enter a group size to see an estimated per-person cost based on our cohort baseline. You can copy a short summary to include in a booking request.</p>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px">
        <div>
          <label>Group size</label>
          <input id="groupSize" type="number" min="1" value="6">
        </div>
        <div>
          <label>Format</label>
          <select id="cohortFormat"><option value="standard">Cohort (60m)</option><option value="extended">Extended (90m)</option><option value="mini">Mini (45m)</option></select>
        </div>
      </div>

      <div style="display:flex;gap:10px;margin-top:12px;align-items:center">
        <button id="calc" class="btn">Calculate</button>
        <button id="copyPlan" class="btn" style="background:#fff;color:var(--muted);border:1px solid rgba(10,10,10,0.06)">Copy plan</button>
        <div id="estimate" style="margin-left:12px;font-weight:800;color:var(--muted)">—</div>
      </div>

      <pre id="planOut" style="margin-top:12px;background:#fff;padding:12px;border-radius:8px;border:1px dashed rgba(10,10,10,0.04)">No estimate yet.</pre>
    </section>

    <footer style="margin-top:18px;color:var(--muted);font-size:13px">For workplace bookings and recurring cohorts, contact <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</footer>
  </main>

  <script>
    // Reveal
    document.addEventListener('DOMContentLoaded',function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('.reveal');
      if(prefersReduced) els.forEach(e=>e.classList.add('visible'));
      else if('IntersectionObserver' in window){
        const io = new IntersectionObserver((entries,obs)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); obs.unobserve(en.target); } }); },{threshold:0.12});
        els.forEach(e=>io.observe(e));
      } else els.forEach(e=>e.classList.add('visible'));

      // Planner logic
      const calc = document.getElementById('calc');
      const copyPlan = document.getElementById('copyPlan');
      const estimate = document.getElementById('estimate');
      const planOut = document.getElementById('planOut');

      function compute(){
        const size = Math.max(1,parseInt(document.getElementById('groupSize').value||6,10));
        const format = document.getElementById('cohortFormat').value;
        let per = 28; // baseline per-person
        if(format==='extended') per = 36;
        if(format==='mini') per = 22;
        // bulk discount
        if(size>=12) per = Math.round(per*0.78);
        if(size>=20) per = Math.round(per*0.7);
        const total = per * size;
        return {size,format,per,total};
      }

      calc.addEventListener('click',function(){
        const r = compute();
        estimate.textContent = '$'+r.per+' / person';
        planOut.textContent = 'Cohort plan summary\n---------------------\nGroup size: '+r.size+'\nFormat: '+(r.format==='extended'? 'Extended (90m)': r.format==='mini'? 'Mini (45m)':'Standard (60m)')+'\nEstimated price per person: $'+r.per+'\nEstimated total: $'+r.total+'\nNotes: Price reflects a cohort baseline; travel or special venue add-ons billed separately.';
      });

      copyPlan.addEventListener('click',async function(){
        const text = planOut.textContent;
        if(!text || text.includes('No estimate')) return alert('Calculate first');
        try{ await navigator.clipboard.writeText(text); copyPlan.textContent = 'Copied'; setTimeout(()=>copyPlan.textContent='Copy plan',1200); }
        catch(e){ const ta=document.createElement('textarea'); ta.value=text; document.body.appendChild(ta); ta.select(); try{ document.execCommand('copy'); alert('Copied'); }catch(er){ alert('Copy failed'); } ta.remove(); }
      });
    });
  </script>
</body>
</html>"} 
